    }

    // Global state: how much slack exists on average across open bins.
    // If mean residual is large, we are spread thin -> placing into a bin with high
    // residual wastes a chance to consolidate.
    let mean_r = mean_residual.clamp(0.0, cap);
    let rel_excess = (mean_r - post_residual as f64) / cap;
    score -= rel_excess * 6.0;

    // Last chance to fit: if this is the only bin that can take the item, we should
    // almost always take it rather than open a new bin.
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (future items are unknown, keep options); later, consolidate aggressively.
    score += (0.5 - progress) * 5.0;

    // Open-bin pressure: with many bins open, consolidating into fewer is valuable.
    let ob = open_bins_count as f64;
    score += (ob / (ob + 6.0)) * 4.0;

    // Mild preference for leaving residual that is a "nice" modular chunk (multiple of 10)
    // reduces awkward fragments for integer-sized items.
    let rem = post_residual % 10;
    if rem == 0 {
        score -= 2.0;
    } else {
        score += rem as f64 * 0.12;
    }

    // Penalize leftovers that are very small (true unusable dust) moderately extra.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 0.5;
    }

    // Nonlinear coupling: if the bin would end up nearly empty relative to item and
    // there are many fitting alternatives, avoid this bin.
    if !is_new_bin && fitting_bins_count > 1 {
        let frag = (post_residual as f64) / cap;
        score += frag * frag * 10.0;
    }

    score
}
